#!/usr/bin/env bash
S4=/tmp/claude-1000/-home-claude-cto/b1caac4c-9b75-4393-9260-1c72f906f86b/scratchpad; SO=/tmp/claude-1000/-home-claude-cto/25cbd82c-ea4e-46bc-9ee6-3c52fc5dcc1f/scratchpad; W=$SO/hdr/SCRIP; H=$SO/hdr/harness/scripts; cd $W || exit 2
echo "== 0 pristine  $(date +%T)"; CCACHE_DISABLE=1 S4E_NO_BUILD_CACHE=1 make -j8 pristine > $S4/work4-pristine3.log 2>&1; echo "pristine rc=$? compiles=$(grep -c -- ' -c ' $S4/work4-pristine3.log) errors=$(grep -c ' error' $S4/work4-pristine3.log)"
echo "== 1 DONE-WHEN"; S4E_HOME=$SO/hdr bash $S4/dw4.sh 2>&1 | tail -1 | cut -c1-240
echo "== 2 R5-prime"; WO=/tmp/si_objs$(printf %s "$W" | tr / -)
bash $H/util_objects_identical_stripped.sh --no-comdat --moved $S4/hdr4_moved.txt $SO/parent-objs-step4/obj $WO $SO/parent-objs-step4/out $W/out > $S4/r5-step4b.log 2>&1; echo "R5-prime rc=$? :: $(grep '^objects=' $S4/r5-step4b.log | cut -c1-300)"; grep -E '^(DIFF|ONLY)' $S4/r5-step4b.log | head -12 | cut -c1-200
echo "== 3 order"; python3 -I $S4/hdr_order.py --root $W --cmds $S4/make-n.txt --out $S4/order-child.json 2>&1 | tail -1; python3 -I $S4/order_cmp.py $S4/order-parent.json $S4/order-child.json /home/claude_cto/SCRIP/src $W/src 2>&1 | tail -1
echo "== 4 style"; files=$(git diff --name-only HEAD -- src | grep -E '\.(c|cpp|h|inc)$' | while read f; do [ -f "$f" ] && echo "$f"; done; git ls-files --others --exclude-standard src | grep -E '\.(c|cpp|h|inc)$'); python3 ../harness/scripts/util_reflow_200.py --check $files 2>&1 | tail -1 | cut -c1-160; python3 ../harness/scripts/strip_comments.py --check $files 2>&1 | tail -1 | cut -c1-160
echo "== 5 smokes  $(date +%T)"; for l in snobol4 snocone rebus icon prolog pascal raku scrip_all_modes; do S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash ../harness/scripts/test_smoke_$l.sh > $S4/smoke4b-$l.log 2>&1; echo "SMOKE $l rc=$?"; done
echo "== 6 the gates that read emit.cpp or the planner"; for g in test_gate_zd_omega_head_acceptance.sh test_gate_no_header_reaches_more_units_than_its_users.sh test_gate_emit_fields_read_by_a_template_have_a_writer.sh test_gate_fb_adopt_one_predicate.sh test_gate_planner_six_passes_read_no_emitter_state.sh test_gate_dyn_caps_ratchet.sh; do f=../harness/scripts/$g; t0=$(date +%s); S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash $f > $S4/gate4b-$g.log 2>&1; echo "GATE $g rc=$? $(( $(date +%s) - t0 ))s :: $(grep -E 'GATE (OK|PASS|FAIL|RED|GREEN|UNPROVEN)|⛔|REFUSE|verdict' $S4/gate4b-$g.log | tail -1 | cut -c1-110)"; done
echo "REPROOF DONE $(date +%T)"
